            /**
            Request of service uavcan.protocol.AccessCommandShell
            THIS DEFINITION IS SUBJECT TO CHANGE.
            This service allows to execute arbitrary commands on the remote node's internal system shell.
            Essentially, this service mimics a typical terminal emulator, with one text input (stdin) and two text outputs
            (stdout and stderr). When there's no process running, the input is directed into the terminal handler itself,
            which interprets it. If there's a process running, the input will be directed into stdin of the running
            process. It is possible to forcefully return the terminal into a known state by means of setting the reset
            flag (see below), in which case the terminal will kill all of the child processes, if any, and return into the
            initial idle state.
            The server is assumed to allocate one independent terminal instance per client, so that different clients can
            execute commands without interfering with each other.
            */
            public class AccessCommandShell_Request {
                public const uint fixed_port_id = 6;
                /**
                Input and output should use this newline character.
                */
                public const byte NEWLINE = 10;
                /**
                The server is required to keep the result of the last executed command for at least this time. When this time
                expires, the server may remove the results in order to reclaim the memory, but it is not guaranteed. Hence,
                the clients must retrieve the results in this amount of time.
                */
                public const byte MIN_OUTPUT_LIFETIME_SEC = 10;
                /**
                These flags control the shell and command execution.
                Restarts the shell instance anew; may or may not imply CLEAR_OUTPUT_BUFFERS
                */
                public const byte FLAG_RESET_SHELL = 1;
                /**
                Makes stdout and stderr buffers empty
                */
                public const byte FLAG_CLEAR_OUTPUT_BUFFERS = 2;
                /**
                Output will contain stdout
                */
                public const byte FLAG_READ_STDOUT = 64;
                /**
                Output will be extended with stderr
                */
                public const byte FLAG_READ_STDERR = 128;
                byte flags;
                /**
                If the shell is idle, it will interpret this string. If there's a process running, this string will be piped
                into its stdin.
                If RESET_SHELL is set, new input will be interpreted by the shell immediately.
                */
                [D(128)] byte[,,] input;
            }

            /**
            Response of service uavcan.protocol.AccessCommandShell
            THIS DEFINITION IS SUBJECT TO CHANGE.
            This service allows to execute arbitrary commands on the remote node's internal system shell.
            Essentially, this service mimics a typical terminal emulator, with one text input (stdin) and two text outputs
            (stdout and stderr). When there's no process running, the input is directed into the terminal handler itself,
            which interprets it. If there's a process running, the input will be directed into stdin of the running
            process. It is possible to forcefully return the terminal into a known state by means of setting the reset
            flag (see below), in which case the terminal will kill all of the child processes, if any, and return into the
            initial idle state.
            The server is assumed to allocate one independent terminal instance per client, so that different clients can
            execute commands without interfering with each other.
            */
            public class AccessCommandShell_Response {
                public const uint fixed_port_id = 6;
                /**
                These flags indicate the status of the shell.
