                public const byte FLAG_SHELL_ERROR = 2;
                /**
                There is more stdout to read
                */
                public const byte FLAG_HAS_PENDING_STDOUT = 64;
                /**
                There is more stderr to read
                */
                public const byte FLAG_HAS_PENDING_STDERR = 128;
