                */
                public const byte UNDEFINED = 255;
                byte protocol;
            }

            /**
            This message carries baudrate for tunnel channel_id
            */
            public class SerialConfig {
                public const uint fixed_port_id = 2011;
                /**
                The channelID allows for additional routing between the source and target nodes.
                */
                byte channel_id;
                uint baud;
                [MinMax(0, 16777215)] uint options;
            }

            /**
            This message struct carries arbitrary data in the format of the specified high-level protocol. The message is
            sent as a broadcast but it is expected that the target_node to select which node will process the data. This
            is used instead of a service request to avoid the round trip which impacts high rate messages a send with a
            buffer length of 0 can be used as a keepalive or to trigger initial setup of the link on the target node
            */
            public class Targetted {
                public const uint fixed_port_id = 3001;
                /**
                option flags
                */
                public const byte OPTION_LOCK_PORT = 1;
                tunnel.Protocol protocol;
                /**
                target CAN node ID
                */
                [MinMax(0, 127)] byte target_node;
                /**
                ID of serial device, -1 means the default device
                */
                [MinMax(-16, 15)] sbyte serial_id;
                [MinMax(0, 15)] byte options;
                [MinMax(0, 16777215)] uint baudrate;
                [D(120)] byte[,,] buffer;
            }
        }

        // ═════════════════════════ demo topology ═════════════════════════

        // DSDL describes data types, not a topology: any node may publish any message subject and any node
        // may serve any service. The demo joins two nodes; Node_A is the service client, Node_B the server.

        /**
        <see cref = 'InTS'/>
        <see cref = 'InJAVA'/>
        <see cref = 'InCS'/>
        <see cref = 'InCPP'/>
        <see cref = 'InGO'/>
        <see cref = 'InRS'/>
        */
        struct Node_A : Host { }

        /**
        <see cref = 'InTS'/>
        <see cref = 'InJAVA'/>
        <see cref = 'InCS'/>
        <see cref = 'InCPP'/>
        <see cref = 'InGO'/>
        <see cref = 'InRS'/>
        */
        struct Node_B : Host { }

        interface Bus : Connects<Node_A, Node_B> {
            // Every message type of this root namespace, either direction, no state transition.
            [_____lr_____<(CoarseOrientation, Timestamp, equipment.actuator.ArrayCommand, equipment.actuator.Command, equipment.actuator.Status, equipment.ahrs.MagneticFieldStrength, equipment.ahrs.MagneticFieldStrength2, equipment.ahrs.RawIMU, equipment.ahrs.Solution, equipment.air_data.AngleOfAttack, equipment.air_data.IndicatedAirspeed, equipment.air_data.RawAirData, equipment.air_data.Sideslip, equipment.air_data.StaticPressure, equipment.air_data.StaticTemperature, equipment.air_data.TrueAirspeed, equipment.camera_gimbal.AngularCommand, equipment.camera_gimbal.GEOPOICommand, equipment.camera_gimbal.Mode, equipment.camera_gimbal.Status, equipment.device.Temperature, equipment.esc.RPMCommand, equipment.esc.RawCommand, equipment.esc.Status, equipment.esc.StatusExtended, equipment.gnss.Auxiliary, equipment.gnss.ECEFPositionVelocity, equipment.gnss.Fix, equipment.gnss.Fix2, equipment.gnss.RTCMStream, equipment.hardpoint.Command, equipment.hardpoint.Status, equipment.ice.FuelTankStatus, equipment.ice.reciprocating.CylinderStatus, equipment.ice.reciprocating.Status, equipment.indication.BeepCommand, equipment.indication.LightsCommand, equipment.indication.RGB565, equipment.indication.SingleLightCommand, equipment.power.BatteryInfo, equipment.power.CircuitStatus, equipment.power.PrimaryPowerSupplyStatus, equipment.range_sensor.Measurement, equipment.safety.ArmingStatus, navigation.GlobalNavigationSolution, protocol.CANIfaceStats, protocol.DataTypeKind, protocol.DsdlFile.EntryType, protocol.DsdlFile.Error, protocol.DsdlFile.Path, protocol.GlobalTimeSync, protocol.HardwareVersion, protocol.NodeStatus, protocol.Panic, protocol.SoftwareVersion, protocol.debug.KeyValue, protocol.debug.LogLevel, protocol.debug.LogMessage, protocol.dynamic_node_id.Allocation, protocol.dynamic_node_id.server.Discovery, protocol.dynamic_node_id.server.Entry, protocol.enumeration.Indication, protocol.param.DsdlEmpty, protocol.param.NumericValue, protocol.param.Value, tunnel.Broadcast, tunnel.Protocol, tunnel.SerialConfig, tunnel.Targetted)>]
            struct Messages { }

            // Services: Node_A calls, Node_B responds (RPC shorthand: Call → Return → End).
            (L____________, protocol.AccessCommandShell_Response) protocol_AccessCommandShell(protocol.AccessCommandShell_Request req);
            (L____________, protocol.DsdlFile.BeginFirmwareUpdate_Response) protocol_DsdlFile_BeginFirmwareUpdate(protocol.DsdlFile.BeginFirmwareUpdate_Request req);
            (L____________, protocol.DsdlFile.Delete_Response) protocol_DsdlFile_Delete(protocol.DsdlFile.Delete_Request req);
            (L____________, protocol.DsdlFile.GetDirectoryEntryInfo_Response) protocol_DsdlFile_GetDirectoryEntryInfo(protocol.DsdlFile.GetDirectoryEntryInfo_Request req);
            (L____________, protocol.DsdlFile.GetInfo_Response) protocol_DsdlFile_GetInfo(protocol.DsdlFile.GetInfo_Request req);
            (L____________, protocol.DsdlFile.Read_Response) protocol_DsdlFile_Read(protocol.DsdlFile.Read_Request req);
            (L____________, protocol.DsdlFile.Write_Response) protocol_DsdlFile_Write(protocol.DsdlFile.Write_Request req);
            (L____________, protocol.GetDataTypeInfo_Response) protocol_GetDataTypeInfo(protocol.GetDataTypeInfo_Request req);
            (L____________, protocol.GetNodeInfo_Response) protocol_GetNodeInfo(protocol.GetNodeInfo_Request req);
            (L____________, protocol.GetTransportStats_Response) protocol_GetTransportStats(protocol.GetTransportStats_Request req);
            (L____________, protocol.RestartNode_Response) protocol_RestartNode(protocol.RestartNode_Request req);
            (L____________, protocol.dynamic_node_id.server.AppendEntries_Response) protocol_dynamic_node_id_server_AppendEntries(protocol.dynamic_node_id.server.AppendEntries_Request req);
            (L____________, protocol.dynamic_node_id.server.RequestVote_Response) protocol_dynamic_node_id_server_RequestVote(protocol.dynamic_node_id.server.RequestVote_Request req);
            (L____________, protocol.enumeration.Begin_Response) protocol_enumeration_Begin(protocol.enumeration.Begin_Request req);
            (L____________, protocol.param.ExecuteOpcode_Response) protocol_param_ExecuteOpcode(protocol.param.ExecuteOpcode_Request req);
            (L____________, protocol.param.GetSet_Response) protocol_param_GetSet(protocol.param.GetSet_Request req);
            (L____________, tunnel.Call_Response) tunnel_Call(tunnel.Call_Request req);
        }

        // ═════════════════════════ DSDL metadata attributes ═════════════════════════

        // AdHoc custom attributes: carried into the generated code as constants attached to the entity.

        /** DSDL type version (major, minor) from the file name. */
        public class VersionAttribute : Attribute { public VersionAttribute(long major, long minor) { } }

        /** @union: a tagged union, exactly one field is present. */
        public class UnionAttribute : Attribute { }

        /** @deprecated: the type is scheduled for removal. */
        public class DeprecatedAttribute : Attribute { }

        /** @sealed: no delimiter header, the layout is final. */
        public class SealedAttribute : Attribute { }

        /** @extent in bytes: the maximum serialized size future versions may grow to. */
        public class ExtentAttribute : Attribute { public ExtentAttribute(long bytes) { } }

        /** The DSDL field is a 16-bit IEEE 754 float (carried as float). */
        public class Float16Attribute : Attribute { }

        /** Explicit DSDL cast mode of the field ("truncated"; saturated is the default). */
        public class CastModeAttribute : Attribute { public CastModeAttribute(string mode) { } }

    }
